type U={id:string;source:string;objectives:string[];sections:[string,string][];trap:string;recall:string;answer:string;case:string;caseAnswer:string;qa:[string,string,string,string,string][];formula?:string;example?:string}
const metadata=new Map(canonicalCourses.filter(c=>c.subject==='Pharmacologie').map(c=>[c.id,c]))
const units:U[]=[
{id:'pharma-absorption-distribution',source:'https://www.ncbi.nlm.nih.gov/books/NBK557405/',objectives:['Comparer les principales voies d’administration','Définir biodisponibilité et premier passage','Relier propriétés moléculaires à l’absorption'],sections:[['Pharmacocinétique et voies','La pharmacocinétique décrit le devenir du médicament dans l’organisme : absorption, distribution, métabolisme et excrétion. Une voie orale est pratique mais expose dissolution, dégradation et premier passage intestinal ou hépatique. La voie intraveineuse délivre directement la dose au compartiment central ; voies inhalée, transdermique et muqueuse ont des profils propres.'],['Absorption digestive','Le passage à travers les membranes dépend de liposolubilité, ionisation, pH, surface d’échange, perfusion, formulation et motilité. Les molécules diffusent, utilisent parfois transporteurs ou voies paracellulaires. Le pH modifie l’ionisation selon pKa, mais ne suffit pas à prédire à lui seul l’absorption d’un médicament dans l’organisme.'],['Biodisponibilité et premier passage','La biodisponibilité F est la fraction de dose qui atteint la circulation systémique sous forme inchangée. Pour une administration IV, F est définie à 1 ; après voie orale, absorption incomplète et métabolisme présystémique peuvent la réduire. L’aire sous la courbe compare l’exposition, avec ajustement de dose lors d’une comparaison de formulations.'],['Distribution','Après arrivée dans le plasma, le médicament se distribue selon perfusion des organes, perméabilité, liaison aux protéines et affinité tissulaire. Seule la fraction libre diffuse généralement, se lie à la cible et est accessible à l’élimination, mais les équilibres de liaison changent au cours du temps. Barrières biologiques limitent certaines distributions.'],['Conséquences de formulation','Aliments, interactions avec transporteurs, libération prolongée et état digestif peuvent modifier vitesse ou quantité absorbée. Une concentration maximale plus basse ne signifie pas forcément une exposition totale moindre. Distinguer vitesse d’absorption, biodisponibilité et distribution évite de confondre des phénomènes différents.']],trap:'Une administration orale n’a pas automatiquement une biodisponibilité de 100 % ; le premier passage et l’absorption incomplète modifient F.',recall:'Quelle est la définition de la biodisponibilité ?',answer:'La fraction de dose atteignant la circulation systémique sous forme inchangée, avec vitesse et étendue décrites selon le contexte.',case:'Deux formes orales ont des pics de concentration différents mais des aires sous la courbe proches. Quelle propriété peut différer surtout ?',caseAnswer:'La vitesse d’absorption, alors que l’exposition totale estimée par l’AUC peut être similaire.',qa:[['Quelle voie définit classiquement une biodisponibilité de référence égale à 1 ?','La voie intraveineuse.','La voie orale.','La voie transdermique.','La voie inhalée.'],['Que mesure principalement l’AUC ?','L’exposition systémique intégrée au cours du temps.','La concentration maximale seulement.','La fraction liée aux protéines uniquement.','La vitesse de clairance rénale seule.'],['Quel mécanisme peut réduire F après prise orale ?','Le métabolisme présystémique intestinal ou hépatique.','La filtration glomérulaire avant absorption.','La liaison au récepteur après distribution.','La demi-vie du métabolite seulement.'],['Quelle fraction est généralement disponible pour diffuser et agir ?','La fraction libre, selon les équilibres du système.','Toute la fraction liée irréversiblement.','La dose non dissoute dans l’intestin.','Le métabolite excrété.'],['Un premier passage est-il une étape de distribution tissulaire ?','Non, il s’agit d’un métabolisme avant l’arrivée systémique.','Oui, par définition il suit l’excrétion.','Oui, il décrit la fixation osseuse.','Non, il correspond à la liaison protéique.']],formula:'F orale ≈ (AUC orale / AUC IV) × (Dose IV / Dose orale)',example:'À doses différentes, comparer les AUC en les rapportant à la dose permet d’estimer la biodisponibilité relative.'},
{id:'pharma-metabolism-elimination',source:'https://www.ncbi.nlm.nih.gov/books/NBK557758/',objectives:['Définir clairance et demi-vie d’élimination','Décrire métabolisme hépatique et excrétion rénale','Interpréter les facteurs modifiant l’exposition'],sections:[['Élimination et clairance','La clairance est le volume apparent de plasma complètement épuré du médicament par unité de temps. Elle agrège plusieurs voies et dépend du médicament, de la fonction des organes, du débit sanguin et des capacités enzymatiques. Elle relie exposition systémique à la dose et à la vitesse d’administration à l’état d’équilibre.'],['Métabolisme','Le foie transforme des molécules par réactions de phase I — oxydation, réduction ou hydrolyse — et de phase II, souvent conjugaison. Ces catégories sont utiles mais les voies se chevauchent. Le métabolisme peut inactiver, activer une prodrogue ou produire un métabolite actif ou toxique ; la structure ne prédit pas seule le résultat clinique.'],['Clairance rénale','La clairance rénale résulte de filtration glomérulaire de la fraction libre, sécrétion tubulaire et réabsorption. Débit urinaire, pH urinaire, transporteurs et fonction rénale influencent l’excrétion de certaines molécules. Une estimation de fonction rénale n’est pas identique à une concentration plasmatique du médicament.'],['Demi-vie','En cinétique linéaire monocompartimentale, t½=0,693×Vd/CL. Une clairance plus grande raccourcit généralement la demi-vie si Vd reste stable ; un Vd plus grand l’allonge si CL est stable. En cinétiques multicompartimentales ou non linéaires, une demi-vie unique résume moins bien les profils.'],['Adaptation conceptuelle','Une atteinte hépatique ou rénale peut modifier exposition ou métabolites, mais l’effet varie selon la voie d’élimination et la marge thérapeutique. Les interactions enzymatiques modifient aussi concentrations. Les décisions de prescription reposent sur le résumé des caractéristiques, le contexte clinique et les recommandations, pas sur une formule isolée.']],trap:'La demi-vie dépend à la fois du volume apparent de distribution et de la clairance ; elle n’est pas une constante indépendante du patient.',recall:'Quelle relation lie demi-vie, Vd et clairance en modèle simple ?',answer:'t½ = 0,693 × Vd / CL.',case:'La clairance diminue tandis que Vd reste stable dans un modèle linéaire. Quel changement qualitatif attendre ?',caseAnswer:'La demi-vie tend à augmenter, car t½ varie inversement avec CL.',qa:[['Dans un modèle simple, quelle relation décrit t½ ?','0,693 × Vd / CL.','CL / Vd seulement.','Dose × clairance.','F / AUC.'],['Que mesure la clairance ?','Un volume de plasma épuré par unité de temps.','La fraction de dose liée à l’albumine.','La quantité totale présente dans le corps.','Le temps jusqu’à absorption complète.'],['Quel processus élimine une molécule du filtrat en la ramenant vers le sang ?','La réabsorption tubulaire.','La sécrétion tubulaire.','La filtration glomérulaire.','La conjugaison hépatique.'],['Une prodrogue est-elle toujours inactive après métabolisme ?','Non, le métabolisme peut générer sa forme active.','Oui, toute biotransformation inactive la molécule.','Oui, elle est excrétée avant transformation.','Non, elle ne peut être administrée par voie orale.'],['À clairance identique, que fait une hausse de Vd dans le modèle simple ?','Elle allonge la demi-vie.','Elle raccourcit la demi-vie.','Elle fixe la biodisponibilité à 1.','Elle n’a jamais de lien avec t½.']],formula:'t½ = 0,693 × Vd / CL',example:'Si Vd augmente sans variation de CL, le médicament reste davantage dans les compartiments tissulaires et sa demi-vie calculée augmente.'},
{id:'pharma-targets-receptors-types',source:'https://www.ncbi.nlm.nih.gov/books/NBK507791/',objectives:['Identifier les grandes familles de cibles pharmacologiques','Relier cible à la vitesse et voie de transduction','Distinguer cible directe et réponse physiologique'],sections:[['Cibles pharmacologiques','Les médicaments agissent sur des protéines et parfois acides nucléiques : récepteurs, enzymes, canaux ioniques, transporteurs ou composants structuraux. La cible explique un mécanisme moléculaire, mais la réponse observée dépend aussi du tissu, de l’expression, de la réserve de cible et des circuits physiologiques.'],['Récepteurs couplés aux protéines G','Les RCPG traversent la membrane plusieurs fois et activent protéines G, seconds messagers ou voies enzymatiques. Leur signal peut être amplifié et modulé par désensibilisation ou internalisation. Le délai d’action dépend de la cascade et ne se déduit pas du seul nom de la cible.'],['Récepteurs-canaux','Les récepteurs ionotropes sont des canaux activés par un ligand ; leur ouverture change rapidement les flux ioniques et le potentiel membranaire. Les canaux voltage-dépendants sont aussi des cibles fréquentes. Sélectivité ionique, état du canal et distribution tissulaire déterminent l’effet d’un bloqueur ou modulateur.'],['Enzymes et transporteurs','Un inhibiteur enzymatique réduit la formation de produit ou augmente un substrat, selon la voie. Un transporteur peut assurer entrée, sortie ou recapture d’un soluté. La direction de l’effet dépend du gradient, du tissu et des voies alternatives ; bloquer une protéine n’implique pas toujours une réponse clinique uniforme.'],['Sélectivité et effets hors cible','La sélectivité dépend des concentrations, affinités et cibles exprimées. À forte exposition, un médicament peut agir sur d’autres protéines et causer effets indésirables. La cible principale ne décrit pas l’ensemble du mécanisme, des métabolites ou des adaptations à long terme.'],['Transduction et réponse','Pour passer de la fixation à l’effet, suivre la chaîne cible → transduction → réponse cellulaire → conséquence d’organe. Une même cible peut déclencher des réponses différentes selon les tissus et les effecteurs exprimés ; inversement, plusieurs cibles peuvent converger vers un effet similaire. Un agoniste partiel produit une réponse plafonnée même si toutes les cibles sont occupées, alors qu’un antagoniste bloque l’action d’un agoniste sans activer lui-même le système. Distinguer affinité, activité intrinsèque et sélectivité aide à ne pas confondre fixation moléculaire et bénéfice clinique. Les courbes concentration-effet doivent être interprétées dans les conditions expérimentales décrites.']],trap:'Bloquer une cible ne permet pas, sans connaître le tissu et le couplage, de prédire entièrement l’effet physiologique.',recall:'Quelles sont quatre grandes familles de cibles médicamenteuses ?',answer:'Récepteurs, enzymes, canaux ioniques et transporteurs.',case:'Un ligand ouvre directement un pore ionique en quelques millisecondes. Quelle classe de cible est concernée ?',caseAnswer:'Un récepteur-canaux ionotrope, dont l’activation modifie rapidement les flux ioniques.',qa:[['Quelle cible peut déclencher directement un flux ionique rapide ?','Un récepteur-canaux ionotrope.','Une enzyme nucléaire uniquement.','Une protéine de transport plasmatique.','Une immunoglobuline circulante.'],['Quel système est associé aux RCPG ?','Protéines G et seconds messagers.','Ouverture toujours directe d’un pore sans intermédiaire.','Clivage du médicament dans l’estomac uniquement.','Synthèse d’ADN par le ligand.'],['Que peut faire un inhibiteur enzymatique ?','Modifier formation du produit ou concentration du substrat.','Ouvrir nécessairement tous les canaux ioniques.','Empêcher toute distribution.','Fixer automatiquement l’EC50 à zéro.'],['De quoi dépend la sélectivité réelle d’un médicament ?','Des concentrations, affinités et cibles exprimées.','Uniquement de son nom commercial.','Uniquement de sa voie orale.','De la couleur du comprimé.'],['Une cible principale explique-t-elle tous les effets indésirables ?','Non, effets hors cible, tissus et métabolites comptent aussi.','Oui, elle suffit pour tout prédire.','Oui, si l’affinité est forte.','Non, les médicaments n’ont pas de cibles.']]},
{id:'pharma-pharmacodynamics-potency-efficacy',source:'https://www.ncbi.nlm.nih.gov/books/NBK507791/',objectives:['Distinguer puissance et efficacité','Interpréter agonisme partiel et antagonisme','Lire les paramètres d’une courbe dose-effet'],sections:[['Réponse graduelle','La pharmacodynamie décrit les effets et mécanismes d’action. Une courbe graduelle relie la dose ou concentration à l’amplitude d’un effet dans un système donné. Emax représente l’effet maximal mesuré ; EC50 est la concentration produisant la moitié de cet effet selon le modèle utilisé.'],['Puissance','La puissance compare la quantité nécessaire pour obtenir un effet défini, souvent décrite par EC50. Une courbe déplacée vers la gauche peut signaler une plus grande puissance dans ce système. La puissance ne signifie pas que le médicament est meilleur, plus sûr ou d’effet maximal supérieur.'],['Efficacité et agonisme partiel','L’efficacité traduit la capacité d’un ligand à produire une réponse. Un agoniste plein atteint l’effet maximal du système de référence ; un agoniste partiel a un plafond plus faible. En présence d’un agoniste plein, il peut réduire la réponse en occupant les mêmes récepteurs.'],['Antagonisme','Un antagoniste compétitif réversible décale souvent la courbe de l’agoniste vers la droite sans réduire Emax si l’antagonisme est surmontable. Un antagonisme non compétitif ou insurmontable peut diminuer l’effet maximal. Les profils dépendent du système et de la durée d’équilibre.'],['Comparaison utile','EC50 et affinité Kd ne sont pas synonymes : amplification, réserve de récepteurs et couplage influencent la réponse. Les comparaisons exigent même tissu, protocole et endpoint. Une différence de puissance ne permet pas de comparer directement les doses cliniques entre médicaments.']],trap:'Puissance et efficacité sont différentes : un médicament plus puissant n’a pas forcément un effet maximal plus important.',recall:'Que représente Emax sur une courbe concentration-réponse ?',answer:'L’effet maximal observé dans le système expérimental défini.',case:'Un ligand produit un plafond inférieur même quand sa concentration augmente fortement. Quel profil évoque-t-il ?',caseAnswer:'Un agoniste partiel, dont l’efficacité maximale dans le système est moindre.',qa:[['Quel paramètre représente l’effet maximal observé ?','Emax.','EC50.','Kd uniquement.','La clairance.'],['Que traduit une EC50 plus faible dans un même système ?','Une plus grande puissance apparente pour atteindre la demi-réponse.','Un Emax nécessairement supérieur.','Une demi-vie plus courte.','Une biodisponibilité absolue plus forte.'],['Quel est le profil d’un agoniste partiel ?','Il active le récepteur mais atteint un effet maximal moindre.','Il se lie sans aucune efficacité dans tous les tissus.','Il augmente toujours Emax au-delà du système.','Il n’a aucune affinité.'],['Quel effet classique d’un antagoniste compétitif surmontable ?','Déplacement vers la droite sans baisse d’Emax dans le modèle idéal.','Baisse obligatoire d’Emax sans déplacement.','Disparition de toute liaison.','Hausse de clairance du ligand.'],['EC50 est-elle identique à Kd par définition ?','Non, la transduction et la réserve de récepteurs séparent réponse et liaison.','Oui, dans tous les systèmes.','Oui, si l’effet est mesuré.','Non, car les deux sont des unités de temps.']],formula:'Effet ≈ Emax × C/(EC50+C) dans un modèle simple de Hill, coefficient 1',example:'À C=EC50, le modèle simple prévoit la moitié d’Emax ; cela ne signifie pas une occupation de 50 % dans tous les systèmes.'},
{id:'pharma-distribution-plasma-protein-binding',source:'https://www.ncbi.nlm.nih.gov/books/NBK545280/',objectives:['Définir le volume apparent de distribution','Expliquer liaison protéique réversible et fraction libre','Relier distribution aux concentrations mesurées'],sections:[['Volume apparent de distribution','Vd est un volume théorique égal à la quantité totale de médicament dans l’organisme divisée par sa concentration plasmatique. Ce n’est pas nécessairement un espace anatomique. Une valeur élevée suggère une concentration plasmatique faible relativement à la quantité présente, souvent en raison d’une distribution tissulaire importante.'],['Liaison aux protéines','Albumine, alpha-1-glycoprotéine acide et protéines spécifiques peuvent lier des médicaments de façon réversible. La fraction libre est généralement celle qui diffuse, interagit avec la cible et peut être filtrée. L’équilibre entre formes libres et liées varie avec concentration, affinité, maladie et autres ligands.'],['Conséquences pharmacocinétiques','Liaison tissulaire, lipophilie, ionisation, perfusion et barrières modifient Vd. Une redistribution entre plasma et tissus peut prolonger la présence apparente. La concentration totale mesurée peut ne pas refléter directement la concentration libre active lorsque la liaison varie.'],['Interactions et interprétation','Deux substances peuvent se concurrencer pour une liaison, mais un déplacement plasmatique transitoire ne prédit pas à lui seul une interaction clinique durable : distribution et élimination rétablissent parfois un nouvel équilibre. La clairance du médicament libre et sa marge thérapeutique sont des éléments importants.'],['Calcul et limites','Vd dépend de la dose administrée et de la concentration au temps de référence, notamment après distribution selon le modèle. Il varie selon individu et méthode. Il doit être distingué du volume plasmatique, du volume extracellulaire et de la quantité réellement présente dans un organe.']],trap:'Le volume apparent de distribution est théorique ; une valeur élevée ne signifie pas que le médicament occupe littéralement ce volume de liquide.',recall:'Comment définit-on le volume apparent de distribution ?',answer:'Vd = quantité totale présente dans l’organisme divisée par la concentration plasmatique mesurée.',case:'Une faible concentration plasmatique coexiste avec une quantité corporelle importante. Quelle interprétation pharmacocinétique est possible ?',caseAnswer:'Un Vd apparent élevé, compatible avec une distribution tissulaire importante.',qa:[['Quelle formule définit Vd ?','Quantité corporelle / concentration plasmatique.','Concentration / quantité éliminée par minute.','Dose orale / biodisponibilité.','AUC / demi-vie.'],['Vd correspond-il forcément à un volume anatomique réel ?','Non, c’est un volume apparent calculé.','Oui, toujours le volume plasmatique.','Oui, le volume intracellulaire exact.','Non, il s’exprime uniquement en masse.'],['Quelle fraction est en général la plus directement disponible pour diffuser ?','La fraction libre à l’équilibre.','La totalité liée de manière covalente.','La molécule déjà éliminée.','La fraction fixée irréversiblement aux tissus.'],['Une hausse de Vd peut-elle allonger t½ si CL reste constante ?','Oui, dans le modèle simple t½ est proportionnelle à Vd.','Non, Vd et demi-vie ne sont jamais liés.','Oui, car elle diminue automatiquement l’AUC à dose fixe.','Non, elle rend F égale à 1.'],['Le déplacement d’un médicament des protéines prédit-il seul la toxicité ?','Non, redistribution et clairance modulent l’effet clinique.','Oui, toute augmentation transitoire de fraction libre cause une toxicité.','Oui, sans dépendre de la marge thérapeutique.','Non, la fraction libre ne joue aucun rôle.']],formula:'Vd = quantité présente dans l’organisme / concentration plasmatique',example:'Une dose corporelle estimée à 500 mg avec concentration 10 mg/L correspond à Vd apparent de 50 L.'},
{id:'pharma-hepatic-metabolism-cytochrome-p450',source:'https://www.ncbi.nlm.nih.gov/books/NBK557744/',objectives:['Distinguer réactions de phase I et de phase II','Décrire induction et inhibition enzymatiques','Analyser l’effet d’une interaction métabolique'],sections:[['Biotransformation hépatique','Le métabolisme transforme des molécules en produits généralement plus polaires, mais il peut activer une prodrogue, inactiver le composé ou former un métabolite pharmacologiquement actif ou réactif. Foie et intestin contribuent, avec des enzymes et transporteurs dont l’activité diffère entre individus.'],['Cytochromes P450','Les CYP sont des enzymes oxydatives hépatiques et intestinales impliquées dans le métabolisme de nombreux médicaments. Une même molécule peut être substrat de plusieurs enzymes. Génotype, âge, inflammation, alimentation et co-médicaments peuvent modifier activité enzymatique et exposition.'],['Phase I et II','Les réactions de phase I comprennent oxydation, réduction et hydrolyse ; celles de phase II conjuguent souvent le médicament ou un métabolite à un groupement endogène. Les phases peuvent s’enchaîner ou être absentes ; une conjugaison ne garantit pas dans tous les cas une inactivation complète.'],['Induction et inhibition','Un inhibiteur réduit l’activité d’une enzyme et peut augmenter l’exposition d’un substrat, sauf si le métabolisme active une prodrogue. Un inducteur augmente souvent l’expression ou l’activité, avec délai de mise en place et de disparition. L’effet final dépend de la voie, de la fraction métabolisée et des autres clairances.'],['Prudence d’interprétation','La nomenclature des enzymes seule ne suffit pas pour prédire une interaction. Vérifier substrat, inhibiteur ou inducteur, sens de la transformation, fenêtre temporelle et conséquences rapportées. Les bases réglementaires et résumés des caractéristiques apportent les consignes propres au médicament, à vérifier à jour.']],trap:'L’inhibition d’une enzyme peut augmenter l’exposition d’un médicament actif, mais réduire l’activation d’une prodrogue.',recall:'Quel est le sens habituel de l’effet d’un inhibiteur CYP sur un médicament substrat actif ?',answer:'Il peut diminuer son métabolisme et augmenter son exposition, selon la fraction métabolisée par cette voie.',case:'Une prodrogue nécessite une enzyme pour devenir active ; un inhibiteur de cette enzyme est ajouté. Quel changement est plausible ?',caseAnswer:'La formation du métabolite actif peut diminuer et donc réduire l’effet attendu.',qa:[['Quelle réaction caractérise souvent la phase I ?','Oxydation, réduction ou hydrolyse.','Filtration glomérulaire uniquement.','Liaison au récepteur sans transformation.','Excrétion pulmonaire.'],['Quel effet possible d’un inhibiteur sur un substrat actif ?','Augmentation de l’exposition si son métabolisme est réduit.','Diminution automatique de la concentration.','Activation obligatoire d’une prodrogue.','Modification de sa dose administrée.'],['Pourquoi l’inhibition peut-elle diminuer l’effet d’une prodrogue ?','Elle peut empêcher la formation du métabolite actif.','Elle augmente toujours l’activation.','Elle bloque uniquement l’absorption.','Elle réduit la liaison protéique de façon certaine.'],['L’induction enzymatique a-t-elle un délai ?','Oui, elle dépend généralement d’une augmentation d’activité/expression et peut persister après arrêt.','Non, elle est toujours instantanée et disparaît immédiatement.','Oui, mais uniquement pour voie intraveineuse.','Non, elle est identique à une inhibition compétitive.'],['La phase II inactive toujours les molécules ?','Non, le devenir dépend de la molécule et du métabolite formé.','Oui, sans exception.','Oui, car elle est rénale.','Non, il n’existe pas de phase II.']]},
{id:'pharma-renal-biliary-clearance',source:'https://www.ncbi.nlm.nih.gov/books/NBK557758/',objectives:['Décrire filtration, sécrétion et réabsorption rénales','Expliquer l’élimination biliaire et l’effet du cycle entérohépatique','Relier fonctions d’organe à l’exposition'],sections:[['Filtration glomérulaire','La filtration dépend de la fraction libre et du débit de filtration glomérulaire. Les molécules fortement liées aux protéines sont moins directement filtrées tant que leur liaison reste en équilibre. Une baisse de filtration peut prolonger l’exposition d’un médicament principalement éliminé par le rein.'],['Sécrétion et réabsorption','Des transporteurs tubulaires sécrètent activement certains médicaments du sang vers l’urine ; d’autres peuvent être réabsorbés. Compétition pour un transporteur, pH urinaire, débit et caractéristiques moléculaires modifient le bilan. Les interactions de transport ne se déduisent pas uniquement de la dose ou de la filtration.'],['Élimination biliaire','Le foie peut transférer certaines molécules ou métabolites dans la bile, ensuite excrétée dans l’intestin. Une fraction peut être réabsorbée, créant un cycle entérohépatique et une exposition prolongée. Les métabolites conjugués peuvent parfois être transformés par le microbiote intestinal.'],['Clairances combinées','La clairance totale est la somme des clairances d’organes dans un modèle linéaire approprié. Si une voie représente une faible fraction de l’élimination globale, l’altération isolée de cette voie peut avoir un effet limité ; si elle domine, l’exposition peut changer davantage. Les métabolites actifs compliquent l’analyse.'],['Évaluation','Estimer élimination rénale et hépatique requiert informations propres au composé, mesures et contexte. Des tests de fonction d’organe servent de substituts imparfaits aux capacités d’élimination. En situation réelle, suivre les recommandations et résumés des caractéristiques plutôt que de déduire une dose d’un mécanisme seul.'],['Élimination et contexte clinique','L’élimination rénale dépend du débit de filtration, de la fraction non liée et des transporteurs ; l’élimination biliaire dépend notamment des propriétés moléculaires et des transporteurs hépatiques. La sécrétion peut être saturée ou faire l’objet d’une compétition, tandis que le pH urinaire modifie parfois la réabsorption de molécules ionisables. Une altération d’organe ne permet pas à elle seule de prédire une dose : il faut considérer la voie d’élimination, la marge thérapeutique, les métabolites actifs, l’âge et les recommandations propres au médicament. Le cycle entérohépatique peut prolonger l’exposition, mais il varie avec microbiote, transit et traitements concomitants.']],trap:'La clairance rénale ne se limite pas à la filtration : sécrétion et réabsorption peuvent modifier fortement l’excrétion.',recall:'Quels trois processus déterminent classiquement l’excrétion rénale ?',answer:'Filtration glomérulaire, sécrétion tubulaire et réabsorption tubulaire.',case:'Une molécule excrétée dans la bile est réabsorbée depuis l’intestin après déconjugaison. Quel cycle peut prolonger son exposition ?',caseAnswer:'Le cycle entérohépatique.',qa:[['Quels processus composent l’excrétion rénale ?','Filtration, sécrétion et réabsorption.','Absorption, distribution et liaison uniquement.','Conjugaison et ventilation pulmonaire.','Récepteur, second messager et internalisation.'],['Quelle fraction est principalement filtrée au glomérule ?','La fraction libre, dans les conditions habituelles.','La fraction liée irréversiblement à l’albumine.','La totalité des molécules tissulaires.','Uniquement les métabolites biliaires.'],['Quel processus transfère un médicament du sang vers la lumière tubulaire via transporteur ?','La sécrétion tubulaire.','La réabsorption tubulaire.','La filtration hépatique.','Le cycle entérohépatique.'],['Qu’est-ce qui peut prolonger une exposition après excrétion biliaire ?','La réabsorption intestinale : cycle entérohépatique.','La filtration glomérulaire directe.','La liaison au canal sodique.','La dilution du médicament dans le plasma.'],['Comment s’additionnent les clairances d’organes dans un modèle simple ?','La clairance totale est la somme des clairances contribuant à l’élimination.','Elles se multiplient toujours.','La plus faible annule les autres.','Elles sont égales à la biodisponibilité.']]},
{id:'pharma-repeated-dosing-steady-state',source:'https://www.ncbi.nlm.nih.gov/books/NBK553132/',objectives:['Définir l’état d’équilibre lors de doses répétées','Estimer le délai vers le plateau par demi-vies','Distinguer dose de charge et dose d’entretien'],sections:[['Accumulation','Lors d’administrations répétées, une dose peut être administrée avant élimination complète de la précédente. La concentration augmente jusqu’à ce que l’apport moyen égale l’élimination moyenne : état d’équilibre. Le profil oscille entre pics et creux selon dose, intervalle, absorption et demi-vie.'],['Délai vers état d’équilibre','En cinétique linéaire d’ordre un, environ quatre à cinq demi-vies conduisent près du plateau, quelle que soit la dose d’entretien. Ce délai dépend de la demi-vie et non d’une multiplication arbitraire des doses. Une variation de clairance modifie à la fois plateau attendu et délai.'],['Doses d’entretien','La vitesse d’administration et la dose d’entretien compensent la clairance afin de maintenir une exposition cible. À l’état d’équilibre, l’exposition moyenne dépend de biodisponibilité, dose par temps et clairance. Les pics et creux dépendent aussi de l’intervalle et de la formulation.'],['Dose de charge','Une dose de charge vise à atteindre plus vite une concentration cible lorsque le délai naturel vers l’équilibre serait trop long. En modèle simple, elle dépend du volume apparent de distribution et de la concentration souhaitée, corrigée par biodisponibilité. Elle ne remplace pas les doses d’entretien.'],['Limites pratiques','La cinétique peut être non linéaire si enzymes saturables, interactions ou changements physiologiques interviennent. Une concentration mesurée doit être interprétée selon le moment du prélèvement et l’intervalle. Les objectifs et marges thérapeutiques sont spécifiques au médicament et au contexte clinique.']],trap:'L’état d’équilibre ne s’atteint pas instantanément après une dose ; le délai est principalement gouverné par la demi-vie.',recall:'Combien de demi-vies faut-il approximativement pour approcher l’état d’équilibre ?',answer:'Environ quatre à cinq demi-vies dans une cinétique linéaire simple.',case:'Un médicament à longue demi-vie doit rapidement atteindre une exposition cible. Quel principe pharmacocinétique permet d’accélérer l’approche du plateau ?',caseAnswer:'Une dose de charge peut rapprocher plus rapidement la concentration cible, puis les doses d’entretien compensent l’élimination.',qa:[['Qu’atteint-on à l’état d’équilibre ?','L’apport moyen égale l’élimination moyenne.','Toute élimination s’arrête.','La concentration devient constante sans oscillations.','La biodisponibilité devient égale à 1.'],['Quel délai approximatif approche le plateau simple ?','Quatre à cinq demi-vies.','Une demi-vie exactement.','Dix intervalles indépendamment de t½.','Un délai nul après dose de charge.'],['Quel paramètre gouverne le temps d’approche au plateau ?','La demi-vie dans le modèle linéaire.','La taille du comprimé seulement.','Le nom de la cible.','La concentration maximale souhaitée uniquement.'],['Quel est le rôle d’une dose de charge ?','Approcher rapidement une concentration cible avant l’équilibre naturel.','Maintenir seule l’exposition indéfiniment.','Réduire la demi-vie moléculaire.','Annuler la clairance.'],['Une dose de charge remplace-t-elle l’entretien ?','Non, l’entretien compense ensuite l’élimination.','Oui, toujours.','Oui si la biodisponibilité est orale.','Non, elle bloque les récepteurs.']],formula:'Dose de charge ≈ Cible × Vd / F ; débit d’entretien ≈ CL × Cible / F',example:'Une demi-vie plus longue retarde l’état d’équilibre ; changer la dose d’entretien change le plateau mais pas le délai dans un modèle linéaire.'},
{id:'pharma-pharmacovigilance-reporting',source:'https://ansm.sante.fr/',objectives:['Définir la pharmacovigilance après mise sur le marché','Décrire les voies françaises de déclaration','Distinguer signalement et preuve de causalité'],sections:[['Surveillance continue','Les essais préalables à l’autorisation ne peuvent détecter tous les effets rares, retardés ou dépendant de populations peu représentées. La pharmacovigilance recueille, analyse et prévient les risques liés aux médicaments après commercialisation, en complément des données expérimentales et des études.'],['Effet indésirable et suspicion','Un effet indésirable est une réponse nocive et non voulue associée à un médicament dans les définitions réglementaires applicables. Une déclaration spontanée porte sur une suspicion et contribue à la détection de signaux ; elle ne démontre pas à elle seule un lien causal.'],['Organisation française','En France, les signalements sont analysés notamment par le réseau des centres régionaux de pharmacovigilance et transmis aux autorités compétentes. Les professionnels et usagers peuvent déclarer selon les modalités officielles en vigueur. Les obligations légales et circuits évoluent : se référer aux pages institutionnelles à jour.'],['Imputabilité et signal','L’analyse confronte chronologie, sémiologie, déchallenge ou réintroduction quand observables, causes alternatives et données connues. Une série de cas peut former un signal nécessitant vérification. Le signal est une hypothèse de risque à évaluer, pas une estimation directe d’incidence ni une preuve définitive.'],['Prévention et communication','Les conclusions peuvent conduire à compléter l’information produit, surveiller, restreindre ou retirer un produit après expertise réglementaire. La déclaration doit contenir informations utiles et traçables, sans retarder les soins nécessaires. L’objectif du système est collectif : rendre l’usage plus sûr en améliorant les connaissances.']],trap:'Une déclaration de pharmacovigilance signale une suspicion utile à l’analyse ; elle ne prouve pas isolément que le médicament a causé l’événement.',recall:'Quel est le rôle principal d’un CRPV ?',answer:'Recueillir et évaluer des signalements et contribuer à la surveillance régionale en lien avec le système national.',case:'Un événement rare survient après introduction d’un nouveau produit, sans certitude causale individuelle. Quelle démarche de santé publique est pertinente ?',caseAnswer:'Déclarer la suspicion selon le circuit officiel afin qu’elle contribue à l’évaluation collective du signal.',qa:[['Une déclaration spontanée prouve-t-elle la causalité ?','Non, elle signale une suspicion qui doit être évaluée.','Oui, dès que l’événement suit la prise.','Oui, elle remplace un essai contrôlé.','Non, elle ne peut jamais contribuer à un signal.'],['Quel est le rôle d’un CRPV ?','Recueillir et évaluer les signalements dans le dispositif de pharmacovigilance.','Autoriser seul tous les médicaments.','Fixer les prix des soins.','Réaliser chaque essai clinique.'],['Pourquoi poursuivre la pharmacovigilance après AMM ?','Des risques rares ou tardifs peuvent échapper aux essais préalables.','L’AMM démontre qu’aucun effet indésirable ne surviendra.','Les essais incluent toujours toutes les populations.','La surveillance post-commercialisation remplace le suivi clinique.'],['Qu’est-ce qu’un signal de sécurité ?','Une information suggérant un risque potentiel à investiguer.','Une preuve définitive de causalité.','Un taux d’incidence exact issu d’une déclaration seule.','Une autorisation de mise sur le marché.'],['Où vérifier les modalités françaises actuelles ?','Sur les ressources institutionnelles ANSM et réseau CRPV.','Dans une publicité du produit.','Dans une source anonyme non datée.','Dans la notice d’un médicament sans autre contexte.']]},
{id:'pharma-adverse-drug-reactions-types',source:'https://www.ncbi.nlm.nih.gov/books/NBK599521/',objectives:['Distinguer réactions dose-dépendantes et imprévisibles','Relier facteurs individuels aux effets indésirables','Décrire prévention et déclaration'],sections:[['Définition et contexte','Un effet indésirable médicamenteux est une réponse nocive et non voulue dans un contexte d’utilisation donné. L’évaluation considère médicament, dose, indication, durée, comorbidités, traitements associés et chronologie. Les symptômes peuvent aussi relever de la maladie ou d’une cause indépendante.'],['Type A','Les réactions de type A sont souvent prévisibles à partir de l’action pharmacologique, dose-dépendantes et plus fréquentes. Elles peuvent résulter d’un effet excessif au site visé ou d’un effet pharmacologique sur un autre système. La relation dose-exposition aide à les comprendre, sans suffire à confirmer chaque cas.'],['Type B','Les réactions de type B sont classiquement moins prévisibles, rares, parfois immunologiques ou liées à susceptibilité individuelle. La dichotomie A/B est pédagogique et ne couvre pas parfaitement tous les mécanismes. Une réaction grave nécessite une évaluation clinique et une déclaration selon le contexte.'],['Susceptibilité et interactions','Âge, fonction rénale ou hépatique, génétique, grossesse, fragilité, dose et polypharmacie modifient risques. Les interactions pharmacodynamiques additionnent ou opposent des effets ; les interactions pharmacocinétiques modifient exposition. L’examen systématique des médicaments et de leurs indications contribue à la prévention.'],['Réduire le risque','Informer sur les effets connus, vérifier indications et contre-indications, suivre les paramètres pertinents et réévaluer le traitement sont des principes de sécurité. En cas de suspicion, le signalement documenté aide la collectivité. Les décisions individuelles doivent suivre des référentiels professionnels actualisés.'],['Évaluer et prévenir','Une analyse d’effet indésirable documente médicament suspect, dose, voie, temporalité, déchallenge et éventuelle réintroduction, ainsi que diagnostics alternatifs et traitements concomitants. La gravité, le caractère attendu et l’imputabilité sont des dimensions différentes. La pharmacovigilance agrège les déclarations pour détecter des signaux ; une notification isolée ne prouve pas un lien causal, mais elle peut contribuer à la surveillance. La prévention comprend information compréhensible, conciliation médicamenteuse, surveillance ciblée et réévaluation périodique du rapport bénéfice-risque. Les procédures de déclaration et conduites à tenir dépendent du pays et doivent être vérifiées auprès des autorités compétentes.']],trap:'Le caractère prévisible d’un effet de type A ne signifie pas qu’il est bénin ; sa gravité peut être importante.',recall:'Quelle propriété générale distingue souvent une réaction de type A ?',answer:'Elle est liée à l’action pharmacologique et souvent dose-dépendante et prévisible.',case:'Un effet pharmacologique connu augmente avec l’exposition et suit la dose. Quel type pédagogique évoque-t-il ?',caseAnswer:'Une réaction de type A, tout en évaluant la gravité et le contexte individuel.',qa:[['Quelle caractéristique évoque une réaction de type A ?','Effet pharmacologique souvent dose-dépendant.','Réaction toujours immunologique sans rapport avec la dose.','Absence de toute chronologie.','Effet bénéfique attendu.'],['Une réaction de type A est-elle forcément bénigne ?','Non, une réaction prévisible peut être grave.','Oui, par définition.','Oui, si elle est dose-dépendante.','Non, car les réactions A n’existent pas.'],['Quel mécanisme peut contribuer à une réaction de type B ?','Une susceptibilité individuelle ou un mécanisme immunologique imprévisible.','Toujours un effet attendu proportionnel à la dose.','Une erreur de mesure statistique uniquement.','L’effet placebo uniquement.'],['Que modifie une interaction pharmacocinétique ?','L’exposition au médicament par modification de son devenir.','Uniquement l’opinion du patient.','Seulement la liaison récepteur-effet sans concentration.','Le diagnostic de la maladie.'],['Que signifie la classification A/B ?','Une simplification pédagogique qui ne couvre pas tous les mécanismes.','Une classification exhaustive et absolue.','Une échelle de gravité uniquement.','Une catégorie d’autorisation réglementaire.']]},
{id:'pharma-drug-interactions-mechanisms',source:'https://www.ncbi.nlm.nih.gov/books/NBK599521/',objectives:['Classer interaction pharmacocinétique ou pharmacodynamique','Décrire inhibition, induction et effets additifs','Évaluer pertinence clinique et contexte'],sections:[['Définition','Une interaction médicamenteuse survient lorsqu’un médicament, aliment ou facteur modifie l’exposition ou l’effet d’un autre. Elle peut augmenter, diminuer ou retarder un effet. Une interaction potentielle n’entraîne pas nécessairement une conséquence clinique chez chaque personne.'],['Pharmacocinétique','Une interaction pharmacocinétique change absorption, distribution, métabolisme ou excrétion. Exemples mécanistiques : chélation dans le tube digestif, inhibition ou induction enzymatique, compétition de transporteurs, modification de clairance. La conséquence dépend de la fraction de dose concernée et de la fenêtre temporelle.'],['Pharmacodynamique','Une interaction pharmacodynamique modifie l’effet au niveau physiologique sans nécessairement changer les concentrations : addition de sédation, antagonisme d’effets ou action convergente sur une fonction. Elle peut être recherchée thérapeutiquement ou majorer un risque selon dose et vulnérabilité.'],['Évaluer importance','La pertinence repose sur gravité potentielle, probabilité, marge thérapeutique, durée, voies et alternatives. Distinguer interaction démontrée, mécanisme plausible et simple alerte informatique. La liste de traitements doit inclure automédication et produits de santé pertinents.'],['Prévenir','Les ressources officielles et informations produit décrivent des interactions propres à chaque médicament. La conduite peut demander surveillance, espacement, adaptation ou substitution, selon recommandations validées. Ne pas interrompre ou modifier seul un traitement sur la base d’une interaction théorique.'],['Évaluer une interaction potentielle','Devant deux traitements, vérifier d’abord si l’interaction est pharmacocinétique ou pharmacodynamique, puis son mécanisme, sa temporalité et les données cliniques disponibles. Une variation mesurable de concentration n’entraîne pas toujours un effet pertinent ; une interaction pharmacodynamique peut exister sans changement de concentration. Le risque dépend de l’exposition, de la marge thérapeutique, de la fonction rénale ou hépatique et de la vulnérabilité de la personne. Les bases d’interactions signalent des associations à examiner, mais ne remplacent pas le résumé des caractéristiques, les recommandations nationales ni l’avis d’un professionnel. Ne jamais arrêter ou modifier seul un traitement prescrit.']],trap:'Une alerte d’interaction indique un risque potentiel ; sa pertinence dépend des doses, du contexte, du médicament et des données disponibles.',recall:'Quelle différence fondamentale entre interaction pharmacocinétique et pharmacodynamique ?',answer:'La première modifie le devenir et l’exposition du médicament ; la seconde modifie l’effet biologique sans nécessairement changer sa concentration.',case:'Deux médicaments renforcent la sédation sans modifier les concentrations plasmatiques. Quel type d’interaction est décrit ?',caseAnswer:'Une interaction pharmacodynamique par addition ou potentialisation des effets.',qa:[['Une inhibition enzymatique relève de quel type ?','Pharmacocinétique.','Pharmacodynamique uniquement.','Pharmaceutique sans effet biologique possible.','Épidémiologique.'],['Deux médicaments majorent un même effet sans changer leurs concentrations : quel mécanisme ?','Pharmacodynamique.','Pharmacocinétique rénale uniquement.','Absorption digestive.','Biodisponibilité absolue.'],['Une interaction potentielle est-elle toujours cliniquement importante ?','Non, elle dépend du contexte et de l’exposition.','Oui, toute alerte entraîne un dommage.','Oui, si les médicaments ont des noms proches.','Non, aucune interaction n’a de conséquence.'],['Quel facteur augmente l’attention nécessaire ?','Une marge thérapeutique étroite.','Une couleur différente des comprimés.','Une longue liste de références.','Un effet placebo attendu.'],['Comment agir face à une alerte spécifique ?','Vérifier des ressources fiables et le contexte avant une décision encadrée.','Arrêter automatiquement tous les médicaments.','Doubler la dose.','Ignorer toujours les alertes.']]},
{id:'pharma-drug-development-preclinical',source:'https://www.ema.europa.eu/en/human-regulatory-overview/research-development/clinical-trials-human-medicines',objectives:['Décrire les étapes précliniques de développement','Expliquer sélection de cible et preuve de concept','Distinguer résultats animaux et bénéfice humain'],sections:[['De la question à la cible','Le développement part d’une hypothèse biologique et d’un besoin de santé. La cible est étudiée pour sa plausibilité, son accessibilité et son rôle dans la maladie. Un criblage identifie des molécules candidates, puis optimisation chimique et essais fonctionnels caractérisent activité, sélectivité et propriétés.'],['Pharmacologie non clinique','Les études caractérisent mécanismes et relation exposition-effet dans des systèmes cellulaires et modèles appropriés. Elles renseignent activité, pharmacocinétique et premières limites, mais un modèle ne reproduit jamais parfaitement la maladie humaine. La qualité, pertinence et reproductibilité des méthodes sont essentielles.'],['Toxicologie','Les études de sécurité explorent nature, dose, durée, organes cibles et réversibilité d’effets toxiques selon les exigences réglementaires applicables. Des analyses de sécurité pharmacologique, génotoxicité ou reproduction peuvent être nécessaires selon le produit et le programme. Aucune expérience préclinique ne garantit le risque nul chez l’humain.'],['Sélection d’un candidat','Le choix combine puissance, sélectivité, exposition, formulation, stabilité, production et marge de sécurité. Une molécule très active in vitro peut échouer faute d’exposition, de tolérance ou de bénéfice pertinent. L’ensemble des données soutient une demande d’essai, pas une preuve d’efficacité clinique.'],['Passage à l’humain','Les études précliniques et dossiers réglementaires encadrent le démarrage des essais chez l’humain, avec protocole, surveillance et consentement. L’autorité et les comités examinent les risques, les données et la justification. Les étapes et exigences évoluent selon catégorie du produit et réglementation ; consulter l’EMA et textes applicables.']],trap:'Un résultat favorable chez l’animal ou in vitro est une étape de connaissance, pas une démonstration d’efficacité ou de sécurité chez l’humain.',recall:'Quels grands types d’études non cliniques précèdent les essais humains ?',answer:'Pharmacologie et preuve de mécanisme, pharmacocinétique et études toxicologiques/de sécurité adaptées au candidat.',case:'Un candidat montre une activité cellulaire mais une exposition insuffisante in vivo. Quelle limite de développement révèle ce résultat ?',caseAnswer:'La preuve d’activité in vitro ne garantit pas une exposition pharmacologique suffisante ni un bénéfice en organisme.',qa:[['Que démontre une activité in vitro ?','Un signal expérimental dans un système précis, à confirmer dans d’autres étapes.','L’efficacité clinique certaine.','L’absence d’effet indésirable humain.','L’obtention automatique d’une AMM.'],['À quoi servent des études toxicologiques non cliniques ?','Caractériser certains risques, organes cibles et relations dose/exposition.','Prouver tout risque nul.','Remplacer le consentement.','Fixer le prix public.'],['Un modèle animal reproduit-il exactement une maladie humaine ?','Non, sa transposition est limitée et doit être évaluée.','Oui, par définition.','Oui si la dose est identique.','Non, il n’apporte jamais d’information.'],['Que combine le choix d’un candidat ?','Activité, exposition, sélectivité, sécurité et faisabilité.','Puissance seule.','Couleur et forme du produit.','Résultat d’un test unique.'],['Les études précliniques autorisent-elles le médicament sur le marché ?','Non, elles soutiennent le développement et les demandes d’essai, pas une AMM.','Oui, immédiatement.','Oui si un modèle animal répond.','Non, aucun dossier n’est requis.']]},
{id:'pharma-clinical-trials-phases',source:'https://www.ema.europa.eu/en/human-regulatory-overview/research-development/clinical-trials-human-medicines/clinical-trials-human-medicines',objectives:['Distinguer objectifs généraux des phases I à IV','Décrire randomisation, comparateur et aveugle','Comprendre limites des essais avant autorisation'],sections:[['Phase I','Les premiers essais humains évaluent généralement tolérance, sécurité, pharmacocinétique et parfois pharmacodynamie, souvent chez volontaires sains mais pas toujours selon produit et risque. Les effectifs sont limités et ne permettent pas de détecter des événements très rares. L’escalade de dose et la surveillance sont encadrées.'],['Phases II et III','La phase II explore activité, dose et schéma dans la population concernée, souvent avec effectifs limités. La phase III évalue bénéfice-risque sur davantage de participants et compare à un standard ou comparateur pertinent. Les frontières ne sont pas absolues ; programmes adaptatifs ou maladies rares peuvent s’écarter du schéma classique.'],['Essai contrôlé','Randomisation réduit le déséquilibre de facteurs pronostiques en moyenne ; allocation dissimulée protège le processus d’inclusion. Aveugle limite certains biais de prise en charge ou évaluation. Un comparateur éthique et pertinent, des critères préspécifiés et analyse adaptée renforcent validité interne.'],['Phase IV et après','Après autorisation, études complémentaires et surveillance poursuivent l’évaluation dans des usages plus larges, parfois pour efficacité comparative, sécurité rare ou nouvelles populations. Phase IV n’est pas un unique type de protocole et ne signifie pas que tout risque est déjà connu.'],['Interpréter les résultats','L’essai apporte une estimation dans des conditions et une population données. Critères de jugement, taille d’effet, intervalle, pertes, multiplicité et généralisabilité doivent être examinés. Un résultat statistique n’est pas automatiquement un bénéfice cliniquement pertinent, et les soins courants diffèrent parfois du protocole.']],trap:'Les phases sont des repères de développement et non des étapes rigides identiques pour tous les médicaments.',recall:'Quel objectif général distingue souvent phase II et phase III ?',answer:'La phase II explore activité/dose ; la phase III confirme bénéfice-risque dans une évaluation plus large et comparative.',case:'Un essai de petit effectif observe une bonne tolérance mais ne peut estimer les risques rares. Quelle limite faut-il reconnaître ?',caseAnswer:'La puissance et la durée limitées ne permettent généralement pas de détecter ou quantifier des événements très rares.',qa:[['Quel est un objectif fréquent de phase I ?','Tolérance, sécurité et pharmacocinétique initiales.','Évaluer uniquement la prescription en population réelle à très grande échelle.','Fixer définitivement le remboursement national.','Comparer systématiquement à tous les médicaments existants.'],['Quelle phase explore souvent dose et activité préliminaire ?','Phase II.','Phase IV seulement.','Phase I exclusivement.','Phase III préclinique.'],['Quel rôle a la randomisation ?','Équilibrer en moyenne les facteurs pronostiques connus et inconnus.','Garantir absence de tout biais.','Assurer l’aveugle par elle-même.','Augmenter la biodisponibilité.'],['Pourquoi poursuivre la surveillance après AMM ?','Les événements rares ou tardifs peuvent émerger après exposition large.','L’AMM garantit le risque nul.','Les essais cliniques sont illégaux.','Les phases I–III ne recueillent jamais de données.'],['Les phases sont-elles toujours séquentielles et identiques ?','Non, ce sont des repères avec adaptations selon produit et contexte.','Oui, sans exception.','Non, elles ne servent à rien.','Oui, chaque phase comporte exactement le même effectif.']]},
{id:'pharma-marketing-authorization-pricing',source:'https://www.ema.europa.eu/en/human-regulatory-overview/marketing-authorisation',objectives:['Décrire l’évaluation réglementaire préalable à l’AMM','Distinguer AMM, SMR et ASMR en France','Situer évaluation du remboursement et fixation du prix'],sections:[['Autorisation de mise sur le marché','L’AMM repose sur l’évaluation de qualité, sécurité et efficacité/bénéfice-risque pour les indications demandées. Dans l’Union européenne, différentes voies existent : centralisée, décentralisée, reconnaissance mutuelle et nationale. La voie dépend du produit et du cadre ; une AMM ne signifie pas absence de risque.'],['Évaluation européenne','Dans la procédure centralisée, l’EMA coordonne l’évaluation scientifique et la Commission européenne accorde l’autorisation. Pour d’autres voies, autorités nationales ou procédures coordonnées interviennent. Résumé des caractéristiques, notice, indications, contre-indications et plan de gestion des risques accompagnent la décision.'],['Évaluation française','Après AMM, la Commission de la transparence de la HAS évalue notamment le service médical rendu (SMR) et l’amélioration du service médical rendu (ASMR) selon le cadre français. SMR contribue à l’appréciation de l’intérêt pour la prise en charge ; ASMR compare le progrès par rapport aux alternatives. Ces notions ne sont pas synonymes.'],['Prix et remboursement','Les conditions de remboursement et le prix résultent de procédures distinctes de l’AMM et mobilisent plusieurs acteurs publics, industriels et payeurs. Les critères, accords et dispositifs varient selon le produit et peuvent évoluer. Il faut consulter les décisions et pages officielles en vigueur, plutôt qu’apprendre un montant fixe hors contexte.'],['Parcours et réévaluation','Un médicament peut être autorisé sans remboursement dans une indication donnée, ou avoir des conditions différentes selon les indications. Les preuves nouvelles peuvent conduire à réévaluation, modification de l’information ou décision économique. L’accès dépend aussi disponibilité, organisation et règles applicables.']],trap:'L’AMM autorise une indication selon un rapport bénéfice-risque ; elle ne fixe pas à elle seule le prix ni le taux de remboursement français.',recall:'Que compare l’ASMR ?',answer:'Le progrès thérapeutique apporté par le médicament par rapport aux stratégies ou traitements comparateurs pertinents.',case:'Un médicament obtient une AMM européenne ; son prix français et son remboursement sont encore en discussion. Pourquoi ?',caseAnswer:'L’autorisation de commercialisation et les évaluations françaises d’intérêt/remboursement et négociation du prix sont des étapes distinctes.',qa:[['Que signifie AMM ?','Autorisation de mise sur le marché après évaluation bénéfice-risque et qualité.','Remboursement intégral automatique.','Preuve d’absence de risque.','Fixation d’un prix identique dans l’UE.'],['Que mesure principalement l’ASMR ?','Le progrès relatif par rapport aux alternatives pertinentes.','Le risque absolu individuel.','La qualité industrielle seule.','Le taux de remboursement.'],['Le SMR est-il identique à l’ASMR ?','Non, ils répondent à des questions d’évaluation différentes.','Oui, ce sont deux noms du prix.','Oui, ils sont décidés par l’EMA.','Non, le SMR mesure seulement la toxicité animale.'],['L’AMM fixe-t-elle directement le prix français ?','Non, prix et prise en charge relèvent d’étapes distinctes.','Oui, le prix est uniforme en Europe.','Oui, elle impose 100 % de remboursement.','Non, les médicaments n’ont pas de prix.'],['Quelle source vérifier pour les modalités actuelles ?','Les pages et décisions officielles EMA et HAS.','Un résumé non daté sur un forum.','La publicité de l’industriel seule.','Une valeur mémorisée sans indication.']]},
{id:'pharma-prescription-dispensation-rules',source:'https://www.legifrance.gouv.fr/codes/texte_lc/LEGITEXT000006072665/',objectives:['Décrire les principes de prescription sécurisée','Distinguer prescription, délivrance et conseil pharmaceutique','Repérer les règles spécifiques selon produit'],sections:[['Prescription et responsabilité','Prescrire consiste à décider une stratégie thérapeutique dans le cadre de ses compétences et responsabilités. Une ordonnance doit identifier patient et prescripteur, préciser le traitement et permettre une compréhension sans ambiguïté. Les mentions légalement requises dépendent du produit, du support et de la réglementation en vigueur.'],['Qualité de l’ordonnance','La lisibilité, la dénomination, dosage, forme, voie, posologie, durée ou quantité et renouvellement doivent être cohérents selon le cas. Vérifier allergies connues, traitements associés, fonction d’organe et contre-indications contribue à la sécurité. Les unités et abréviations ambiguës augmentent le risque d’erreur.'],['Dispensation','Le pharmacien analyse la prescription dans le cadre légal, vérifie les éléments nécessaires et délivre le médicament avec conseils adaptés. Des règles particulières encadrent stupéfiants, médicaments à prescription restreinte, dispositifs et ordonnances sécurisées. Substitution et renouvellement obéissent à des conditions légales spécifiques.'],['Information et coordination','Une explication claire couvre prise, durée, précautions et conduite à tenir en cas de question, en évitant les consignes non vérifiées. Le dossier et les échanges entre professionnels doivent respecter secret et règles de partage. En cas d’incertitude, clarification avec le prescripteur ou référentiel officiel est préférable à une interprétation improvisée.'],['Droit évolutif','Le Code de la santé publique et textes d’application fixent le cadre français ; listes, durée de validité et mentions varient selon classe et évoluent. Le présent cours décrit des principes de sécurité et ne remplace pas la vérification des textes consolidés ou des référentiels professionnels au moment de l’exercice.']],trap:'Les mentions d’une ordonnance et sa durée de validité ne sont pas identiques pour tous les médicaments ; vérifier le cadre applicable au produit.',recall:'Quels éléments pratiques réduisent les ambiguïtés d’une prescription ?',answer:'Identifier précisément patient et médicament, dosage, forme, voie, posologie et durée/quantité selon le cadre applicable, avec une écriture claire.',case:'Une ordonnance comporte une posologie ambiguë pour un médicament à règles spécifiques. Quelle conduite sécurisée s’impose avant délivrance ?',caseAnswer:'Faire clarifier la prescription selon les responsabilités et procédures professionnelles, en consultant les textes applicables au produit.',qa:[['Pourquoi la posologie doit-elle être explicite ?','Pour limiter erreurs de dose, voie, fréquence et durée.','Pour remplacer toute vérification pharmaceutique.','Pour garantir l’absence d’effet indésirable.','Pour définir le prix du médicament.'],['Les règles de validité sont-elles identiques pour tout médicament ?','Non, elles peuvent dépendre de la classe et des textes en vigueur.','Oui, sans exception.','Oui, elles sont fixées par le fabricant uniquement.','Non, aucune règle n’existe.'],['Quel rôle joue la dispensation pharmaceutique ?','Analyser la prescription et fournir le médicament avec conseils adaptés.','Autoriser l’AMM.','Remplacer systématiquement le diagnostic.','Fixer le SMR.'],['Face à une prescription ambiguë, quelle attitude est la plus sûre ?','Clarifier auprès du prescripteur selon le circuit approprié.','Deviner la dose habituelle.','Doubler la fréquence.','Supprimer l’information écrite.'],['Quelle source définit le cadre juridique français ?','Le Code de la santé publique et les textes applicables à jour.','Une fiche commerciale seule.','Un ancien polycopié non daté.','Une règle identique dans tous les pays.']]}
]
const term=(source:string)=>source.includes('ansm')?'ANSM · information institutionnelle':source.includes('ema')?'EMA · cadre réglementaire européen':source.includes('legifrance')?'Légifrance · Code de la santé publique':'NCBI Bookshelf · StatPearls / pharmacologie'
export const additionalPharmacologyCourses:Course[]=units.map(u=>{const c=metadata.get(u.id);if(!c)throw new Error(`Cours canonique de pharmacologie absent : ${u.id}`);return{id:u.id,title:c.title,category:c.subject,tag:c.module,minutes:18,structure:null,objectives:u.objectives,sections:u.sections.map(([title,text])=>({title,text})),trap:u.trap,recall:u.recall,answer:u.answer,source:u.source,sources:[{label:term(u.source),url:u.source}],prerequisites:['Pharmacocinétique générale','Physiologie des organes concernés'],...(u.formula?{learning:{formula:{label:'Relation pharmacocinétique',expression:u.formula,explanation:'Modèle simplifié valide sous hypothèses précisées dans le chapitre.'},comparison:{headers:['Paramètre','Sens','Vérification'],rows:[['Dose','Quantité administrée','Voie et intervalle'],['Exposition','Concentration au cours du temps','AUC et prélèvement'],['Élimination','Disparition du médicament','Clairance et demi-vie']]},example:{prompt:u.example??'',steps:['Définir le modèle et les unités.','Insérer les valeurs avec cohérence dimensionnelle.','Interpréter selon les hypothèses.'],result:u.example??''},errors:[{title:'Appliquer une formule hors modèle',detail:'Vérifier linéarité, biodisponibilité, compartiments et unités avant d’interpréter.'}]}}:{}),glossary:[['Pharmacocinétique','Étude de l’absorption, distribution, métabolisme et élimination.'],['Exposition','Concentrations auxquelles l’organisme est soumis dans le temps.'],['Marge thérapeutique','Écart entre expositions associées à l’efficacité et à la toxicité.']],caseStudy:{prompt:u.case,answer:u.caseAnswer},review:{status:'unreviewed',updatedAt:'2026-09-23',sourcesUpdatedAt:'2026-09-23'}}})
export const additionalPharmacologyQuestions:Question[]=units.flatMap(u=>u.qa.map(([prompt,correct,...wrong],i)=>({id:`${u.id}-q${i+1}`,course:u.id,topic:'Pharmacologie',prompt,options:[correct,...wrong],correct:[0],why:[`Réponse correcte : ${correct}`,`Cette proposition confond le mécanisme étudié avec un autre paramètre pharmacologique.`,`Cette proposition n’est pas compatible avec les définitions et conditions du chapitre.`,`Cette proposition affirme davantage que ce que permettent les données.`],difficulty:i<2?'essentiel':'application',format:'single'})))
